import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';class ProductService{final _db=FirebaseFirestore.instance;final _auth=FirebaseAuth.instance;Future<void> createProduct({required String title,required String description,required int price,required String imageUrl,required double latitude,required double longitude,String category='Lainnya',String locationName=''})async{final uid=_auth.currentUser!.uid;final user=await _db.collection('users').doc(uid).get();final product=_db.collection('products').doc();await product.set({'sellerId':uid,'sellerName':user.data()?['name']??user.data()?['email']??'Pengguna Flowa','title':title.trim(),'description':description.trim(),'price':price,'imageUrl':imageUrl,'latitude':latitude,'longitude':longitude,'locationName':locationName,'category':category,'status':'active','createdAt':FieldValue.serverTimestamp(),'updatedAt':FieldValue.serverTimestamp()});}}